package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import com.myproject.video.video_platform.common.enums.products.*;import com.myproject.video.video_platform.common.enums.products.course.LessonType;import com.myproject.video.video_platform.common.enums.entitlement.*;
import com.myproject.video.video_platform.entity.products.*;import com.myproject.video.video_platform.entity.products.course.*;import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.repository.products.course.quiz.*;
import org.springframework.beans.factory.annotation.Autowired;import org.junit.jupiter.api.*;import jakarta.servlet.http.Cookie;
import java.util.*;import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class CatalogQuizMatrixTest extends CatalogProductOwnershipPublicationTest{
 @Autowired QuizRepository quizzes;@Autowired QuizAttemptRepository quizAttempts;
 @AfterEach void quizCleanup(){quizAttempts.deleteAll();}
 record QuizFixture(Product p,CourseSection s,CourseLesson l){}
 QuizFixture fixture(LessonType type){Product p=seed(ProductType.COURSE,owner,"10",ProductStatus.PUBLISHED);CourseSection s=new CourseSection();s.setCourse((CourseProduct)p);s.setTitle("QA quiz section");s.setPosition(1);s=sections.saveAndFlush(s);CourseLesson l=new CourseLesson();l.setSection(s);l.setType(type);l.setTitle("QA "+type);l.setPosition(1);l=lessons.saveAndFlush(l);return new QuizFixture(p,s,l);}
 String url(QuizFixture f){return "/api/lessons/"+f.l().getId()+"/quiz";}
 ObjectNode option(String text,boolean correct,int position){ObjectNode o=mapper.createObjectNode();o.put("text",text);o.put("isCorrect",correct);o.put("position",position);return o;}
 ObjectNode question(String type,int points,int pos){ObjectNode q=mapper.createObjectNode();q.put("title","QA "+type);q.put("type",type);q.put("points",points);q.put("position",pos);q.put("shuffle",true);q.put("explanation","QA explanation "+pos);ArrayNode opts=q.putArray("options");if(type.equals("true_false")){opts.add(option("True",true,1));opts.add(option("False",false,2));}else{opts.add(option("A",true,1));opts.add(option("B",type.equals("multiple_choice_multi"),2));if(type.equals("multiple_choice_multi"))opts.add(option("C",false,3));}return q;}
 ObjectNode draft(String...types){ObjectNode d=mapper.createObjectNode();d.put("passingScore",80);ArrayNode qs=d.putArray("questions");int i=0;for(String type:types)qs.add(question(type,5,++i));return d;}
 JsonNode saveQuiz(String c,String label,QuizFixture f,User caller,JsonNode body,int status)throws Exception{return perform(c,label,mutation(put(url(f)),caller).content(body.toString()),status);}
 JsonNode authorRead(String c,String label,QuizFixture f,User caller,int status)throws Exception{return perform(c,label,get(url(f)).cookie(auth(caller)),status);}
 JsonNode play(String c,String label,QuizFixture f,User caller,int status)throws Exception{var req=get(url(f)+"/play");if(caller!=null)req.cookie(auth(caller));return perform(c,label,req,status);}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder callerMutation(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder req,User u){return u==null?req.cookie(new Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf").contentType(org.springframework.http.MediaType.APPLICATION_JSON):mutation(req,u);}
 JsonNode submit(String c,String label,QuizFixture f,User caller,JsonNode body,int status)throws Exception{return perform(c,label,callerMutation(post(url(f)+"/submit"),caller).content(body.toString()),status);}
 ObjectNode answer(JsonNode q,List<String>selected){ObjectNode a=mapper.createObjectNode();a.put("questionId",q.path("id").asText());ArrayNode ids=a.putArray("selectedOptionIds");selected.forEach(ids::add);return a;}
 ObjectNode answers(ObjectNode...a){ObjectNode b=mapper.createObjectNode();ArrayNode arr=b.putArray("answers");for(var item:a)arr.add(item);return b;}
 List<String> correctIds(JsonNode q){List<String>a=new ArrayList<>();for(JsonNode o:q.path("options"))if(o.path("isCorrect").asBoolean())a.add(o.path("id").asText());return a;}
 void entitled(QuizFixture f,User u){grant(f.p(),u,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);}
 void score(QuizFixture f,JsonNode quiz,JsonNode result,int achieved,int possible,String pct,boolean passed){assertEquals(f.l().getId().toString(),result.path("lessonId").asText());assertEquals(quiz.path("id"),result.path("quizId"));assertEquals(achieved,result.path("totalPointsAchieved").asInt());assertEquals(possible,result.path("totalPointsPossible").asInt());assertEquals(0,new BigDecimal(pct).compareTo(result.path("percentage").decimalValue()));assertEquals(passed,result.path("passed").asBoolean());assertEquals(quiz.path("passingScore"),result.path("passingScore"));assertEquals(quiz.path("questions").size(),result.path("questions").size());}
 void draftIds(JsonNode n){UUID.fromString(n.path("id").asText());Set<String>qids=new HashSet<>(),oids=new HashSet<>();int last=0;for(JsonNode q:n.path("questions")){assertTrue(qids.add(q.path("id").asText()));UUID.fromString(q.path("id").asText());assertTrue(q.path("position").asInt()>=last);last=q.path("position").asInt();int op=0;for(JsonNode o:q.path("options")){assertTrue(o.has("isCorrect"));assertTrue(oids.add(o.path("id").asText()));UUID.fromString(o.path("id").asText());assertTrue(o.path("position").asInt()>=op);op=o.path("position").asInt();}}}
 @Test void quiz001AuthorRoundTripOrderedReplacementRemovesOmittedChildren()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ);ObjectNode body=draft("multiple_choice_single","multiple_choice_multi","true_false");((ObjectNode)body.path("questions").get(0)).put("position",3);((ObjectNode)body.path("questions").get(2)).put("position",1);JsonNode created=saveQuiz("QUIZ-001",role(caller)+"-create-three-types",f,caller,body,200);draftIds(created);assertEquals("true_false",created.path("questions").get(0).path("type").asText());assertEquals(created,authorRead("QUIZ-001",role(caller)+"-saved-author-read",f,caller,200));ObjectNode replacement=(ObjectNode)created.deepCopy();JsonNode removed=replacement.path("questions").get(2).deepCopy();((ArrayNode)replacement.path("questions")).remove(2);((ArrayNode)replacement.path("questions")).add(question("multiple_choice_single",7,4));JsonNode updated=saveQuiz("QUIZ-001",role(caller)+"-replace-one-retain-two",f,caller,replacement,200);draftIds(updated);assertEquals(created.path("id"),updated.path("id"));assertEquals(3,updated.path("questions").size());assertEquals(created.path("questions").get(0),updated.path("questions").get(0));assertEquals(created.path("questions").get(1),updated.path("questions").get(1));assertEquals(updated,authorRead("QUIZ-001",role(caller)+"-replacement-saved",f,caller,200));assertEquals(0,jdbc.queryForObject("select count(*) from quiz_questions where id=?",Integer.class,UUID.fromString(removed.path("id").asText())));for(JsonNode o:removed.path("options"))assertEquals(0,jdbc.queryForObject("select count(*) from quiz_options where id=?",Integer.class,UUID.fromString(o.path("id").asText())));}assertEquals(0,quizAttempts.count());}
 @Test void quiz002MissingDefinitionAndWrongLessonType()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture missing=fixture(LessonType.QUIZ);authorRead("QUIZ-002",role(caller)+"-quiz-absent",missing,caller,404);for(LessonType type:List.of(LessonType.ARTICLE,LessonType.VIDEO)){QuizFixture f=fixture(type);saveQuiz("QUIZ-002",role(caller)+"-wrong-type-"+type,f,caller,draft("multiple_choice_single"),400);assertEquals(type,lessons.findById(f.l().getId()).orElseThrow().getType());assertEquals(0,quizzes.count());}}}
 @Test void quiz003IdentityInvalidChildIdsAndDeletion()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ),other=fixture(LessonType.QUIZ);JsonNode saved=saveQuiz("QUIZ-003",role(caller)+"-target-create",f,caller,draft("multiple_choice_single"),200),untouched=saveQuiz("QUIZ-003",role(caller)+"-unrelated-create",other,caller,draft("true_false"),200);ObjectNode bad=(ObjectNode)saved.deepCopy();bad.put("id",untouched.path("id").asText());JsonNode error=saveQuiz("QUIZ-003",role(caller)+"-mismatched-quiz-ID",f,caller,bad,400);assertTrue(error.path("errors").has("id"));assertEquals(saved,authorRead("QUIZ-003",role(caller)+"-identity-rejection-unchanged",f,caller,200));ObjectNode invalidChildren=(ObjectNode)saved.deepCopy();((ObjectNode)invalidChildren.path("questions").get(0)).put("id","invalid-question-ID");for(JsonNode o:invalidChildren.path("questions").get(0).path("options"))((ObjectNode)o).put("id","invalid-option-ID");JsonNode fresh=saveQuiz("QUIZ-003",role(caller)+"-fresh-UUID-child-fallback",f,caller,invalidChildren,200);draftIds(fresh);assertNotEquals(saved.path("questions").get(0).path("id"),fresh.path("questions").get(0).path("id"));assertEquals(fresh,authorRead("QUIZ-003",role(caller)+"-fresh-children-saved",f,caller,200));perform("QUIZ-003",role(caller)+"-delete-definition",mutation(delete(url(f)),caller),204);authorRead("QUIZ-003",role(caller)+"-deleted-definition",f,caller,404);assertEquals(untouched,authorRead("QUIZ-003",role(caller)+"-unrelated-unchanged",other,caller,200));assertEquals(LessonType.QUIZ,lessons.findById(f.l().getId()).orElseThrow().getType());}}
 @Test void quiz004GeneralValidationPreservesDefinition()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ);JsonNode saved=saveQuiz("QUIZ-004",role(caller)+"-valid-control",f,caller,draft("multiple_choice_single"),200);for(String variant:List.of("empty-questions","null-questions","missing-questions","empty-title","blank-title","null-title","zero-points","negative-points","null-points","zero-options","one-option","null-options","blank-option","null-option-text","score-negative","score-above100")){ObjectNode b=draft("multiple_choice_single");ObjectNode q=(ObjectNode)b.path("questions").get(0);switch(variant){case"empty-questions"->b.set("questions",mapper.createArrayNode());case"null-questions"->b.putNull("questions");case"missing-questions"->b.remove("questions");case"empty-title"->q.put("title","");case"blank-title"->q.put("title","   ");case"null-title"->q.putNull("title");case"zero-points"->q.put("points",0);case"negative-points"->q.put("points",-1);case"null-points"->q.putNull("points");case"zero-options"->q.set("options",mapper.createArrayNode());case"one-option"->((ArrayNode)q.path("options")).remove(1);case"null-options"->q.putNull("options");case"blank-option"->((ObjectNode)q.path("options").get(0)).put("text","   ");case"null-option-text"->((ObjectNode)q.path("options").get(0)).putNull("text");case"score-negative"->b.put("passingScore",-1);case"score-above100"->b.put("passingScore",101);}JsonNode error=saveQuiz("QUIZ-004",role(caller)+"-"+variant,f,caller,b,400);assertTrue(error.path("errors").size()>0);assertEquals(saved,authorRead("QUIZ-004",role(caller)+"-unchanged-after-"+variant,f,caller,200));}assertEquals(0,quizAttempts.count());}}
 @Test void quiz005SingleExactlyOneCorrect()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ);for(int count:List.of(0,2,1)){ObjectNode b=draft("multiple_choice_single");ArrayNode opts=(ArrayNode)b.path("questions").get(0).path("options");for(int i=0;i<2;i++)((ObjectNode)opts.get(i)).put("isCorrect",i<count);JsonNode n=saveQuiz("QUIZ-005",role(caller)+"-correct-count-"+count,f,caller,b,count==1?200:400);if(count==1)assertEquals(n,authorRead("QUIZ-005",role(caller)+"-valid-saved",f,caller,200));else assertTrue(n.path("errors").has("questions[0].options"));}}}
 @Test void quiz006MultiOneOrManyCorrect()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ);for(int count:List.of(0,1,2)){ObjectNode b=draft("multiple_choice_multi");ArrayNode opts=(ArrayNode)b.path("questions").get(0).path("options");for(int i=0;i<3;i++)((ObjectNode)opts.get(i)).put("isCorrect",i<count);JsonNode n=saveQuiz("QUIZ-006",role(caller)+"-correct-count-"+count,f,caller,b,count>0?200:400);if(count>0){assertEquals(n,authorRead("QUIZ-006",role(caller)+"-valid-saved-"+count,f,caller,200));assertEquals(count,correctIds(n.path("questions").get(0)).size());}else assertTrue(n.path("errors").has("questions[0].options"));}}}
 @Test void quiz007TrueFalseOptionLabelsAndCorrectness()throws Exception{for(User caller:List.of(owner,admin)){QuizFixture f=fixture(LessonType.QUIZ);for(String variant:List.of("one-option","three-options","duplicate-labels","invalid-label","zero-correct","two-correct","valid-normalized")){ObjectNode b=draft("true_false");ArrayNode os=(ArrayNode)b.path("questions").get(0).path("options");switch(variant){case"one-option"->os.remove(1);case"three-options"->os.add(option("False",false,3));case"duplicate-labels"->((ObjectNode)os.get(1)).put("text","TRUE");case"invalid-label"->((ObjectNode)os.get(1)).put("text","Maybe");case"zero-correct"->((ObjectNode)os.get(0)).put("isCorrect",false);case"two-correct"->((ObjectNode)os.get(1)).put("isCorrect",true);case"valid-normalized"->{((ObjectNode)os.get(0)).put("text"," TRUE ");((ObjectNode)os.get(1)).put("text"," false ");}}JsonNode n=saveQuiz("QUIZ-007",role(caller)+"-"+variant,f,caller,b,variant.equals("valid-normalized")?200:400);if(variant.equals("valid-normalized"))assertEquals(n,authorRead("QUIZ-007",role(caller)+"-valid-saved",f,caller,200));else assertTrue(n.path("errors").has("questions[0].options"));}}}
 @Test void quiz008AuthorPermissionsAllRolesAndEntitlementNotAuthoring()throws Exception{User outsider=extra("quiz-nonowner-creator",owner);QuizFixture f=fixture(LessonType.QUIZ);JsonNode saved=saveQuiz("QUIZ-008","owner-initial-definition",f,owner,draft("multiple_choice_single"),200);entitled(f,buyer);entitled(f,outsider);for(User caller:Arrays.asList(null,buyer,outsider)){String label=caller==null?"Guest":role(caller);int expected=caller==null?401:403;var getReq=get(url(f));if(caller!=null)getReq.cookie(auth(caller));perform("QUIZ-008",label+"-author-read",getReq,expected);perform("QUIZ-008",label+"-author-PUT",callerMutation(put(url(f)),caller).content(draft("multiple_choice_single").toString()),expected);perform("QUIZ-008",label+"-author-DELETE",callerMutation(delete(url(f)),caller),expected);assertEquals(saved,authorRead("QUIZ-008",label+"-definition-unchanged",f,owner,200));}for(User caller:List.of(owner,admin)){QuizFixture target=fixture(LessonType.QUIZ);JsonNode n=saveQuiz("QUIZ-008",role(caller)+"-author-write-allowed",target,caller,draft("multiple_choice_multi"),200);assertEquals(n,authorRead("QUIZ-008",role(caller)+"-author-read-allowed",target,caller,200));perform("QUIZ-008",role(caller)+"-author-delete-allowed",mutation(delete(url(target)),caller),204);authorRead("QUIZ-008",role(caller)+"-author-delete-persisted",target,caller,404);}assertEquals(0,quizAttempts.count());}
 @Test void quiz009LearnerRedactionExplanationShuffleStableRead()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode author=saveQuiz("QUIZ-009","persisted-definition",f,owner,draft("multiple_choice_single","multiple_choice_multi","true_false"),200);entitled(f,buyer);JsonNode expected=author.deepCopy();for(JsonNode q:expected.path("questions"))for(JsonNode o:q.path("options"))((ObjectNode)o).remove("isCorrect");for(User caller:List.of(buyer,owner,admin)){JsonNode first=play("QUIZ-009",role(caller)+"-play-first",f,caller,200);assertEquals(expected,first);assertEquals(first,play("QUIZ-009",role(caller)+"-play-second",f,caller,200));for(JsonNode q:first.path("questions")){assertTrue(q.path("shuffle").asBoolean());assertTrue(q.path("explanation").asText().startsWith("QA explanation"));for(JsonNode o:q.path("options"))assertFalse(o.has("isCorrect"));}assertEquals(0,quizAttempts.count());}assertEquals(author,authorRead("QUIZ-009","author-correctness-retained",f,owner,200));}
 @Test void quiz010LearnerMissingRevokedGuestDeniedWithOwnerAdminBypass()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-010","definition",f,owner,draft("multiple_choice_single"),200);ObjectNode body=answers(answer(quiz.path("questions").get(0),correctIds(quiz.path("questions").get(0))));play("QUIZ-010","Guest-play",f,null,401);submit("QUIZ-010","Guest-submit-valid-CSRF",f,null,body,401);for(String state:List.of("missing","revoked")){if(state.equals("revoked"))grant(f.p(),buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.REVOKED);play("QUIZ-010",state+"-play",f,buyer,403);submit("QUIZ-010",state+"-submit",f,buyer,body,403);assertEquals(0,quizAttempts.count());}for(User caller:List.of(owner,admin)){play("QUIZ-010",role(caller)+"-bypass-play",f,caller,200);score(f,quiz,submit("QUIZ-010",role(caller)+"-bypass-submit",f,caller,body,200),5,5,"100.0",true);assertTrue(grants.findByUserUserIdAndProductId(caller.getUserId(),f.p().getId()).isEmpty());}assertEquals(2,quizAttempts.count());}
 @Test void quiz011SingleAndTrueFalseCorrectWrongScoring()throws Exception{for(String type:List.of("multiple_choice_single","true_false")){QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-011",type+"-definition",f,owner,draft(type),200);entitled(f,buyer);JsonNode q=quiz.path("questions").get(0);String wrong=q.path("options").get(1).path("id").asText();for(User caller:List.of(buyer,owner,admin)){for(boolean correct:List.of(true,false)){JsonNode result=submit("QUIZ-011",role(caller)+type+"-correct-"+correct,f,caller,answers(answer(q,correct?correctIds(q):List.of(wrong))),200);score(f,quiz,result,correct?5:0,5,correct?"100.0":"0.0",correct);assertEquals(correct,result.path("questions").get(0).path("correct").asBoolean());assertEquals(correct?5:0,result.path("questions").get(0).path("pointsAwarded").asInt());assertEquals(q.path("id"),result.path("questions").get(0).path("questionId"));assertEquals(q.path("explanation"),result.path("questions").get(0).path("explanation"));}}}assertEquals(12,quizAttempts.count());}
 @Test void quiz012MultiExactSetSubsetSupersetDuplicates()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-012","multi-definition",f,owner,draft("multiple_choice_multi"),200);entitled(f,buyer);JsonNode q=quiz.path("questions").get(0);List<String>correct=correctIds(q);String wrong=q.path("options").get(2).path("id").asText();List<List<String>>sets=List.of(correct,List.of(correct.get(0)),List.of(correct.get(0),correct.get(1),wrong),List.of(correct.get(0),correct.get(1),correct.get(0),correct.get(1)));for(User caller:List.of(buyer,owner,admin))for(int i=0;i<sets.size();i++){boolean earns=i==0||i==3;JsonNode result=submit("QUIZ-012",role(caller)+"-answer-set-"+i,f,caller,answers(answer(q,sets.get(i))),200);score(f,quiz,result,earns?5:0,5,earns?"100.0":"0.0",earns);assertEquals(earns,result.path("questions").get(0).path("correct").asBoolean());}assertEquals(12,quizAttempts.count());for(var a:quizAttempts.findAll()){JsonNode normalized=mapper.readTree(a.getAnswersJson());List<String> ids=mapper.convertValue(normalized.path(q.path("id").asText()),List.class);assertEquals(new HashSet<>(ids).size(),ids.size());if(a.getTotalPointsAchieved()>0)assertEquals(new HashSet<>(correct),new HashSet<>(ids));else assertTrue(new HashSet<>(ids).equals(new HashSet<>(sets.get(1)))||new HashSet<>(ids).equals(new HashSet<>(sets.get(2))));}}
 @Test void quiz013OmittedAnswersRoundingAndThresholdEquality()throws Exception{for(Integer threshold:Arrays.asList(0,100,null)){QuizFixture f=fixture(LessonType.QUIZ);ObjectNode b=draft("multiple_choice_single","multiple_choice_single","multiple_choice_single");if(threshold==null)b.putNull("passingScore");else b.put("passingScore",threshold);JsonNode quiz=saveQuiz("QUIZ-013","threshold-"+threshold+"-definition",f,owner,b,200);entitled(f,buyer);for(User caller:List.of(buyer,owner,admin)){for(String shape:List.of("empty","omitted","null")){ObjectNode body=shape.equals("empty")?answers():mapper.createObjectNode();if(shape.equals("null"))body.putNull("answers");score(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-"+shape,f,caller,body,200),0,15,"0.0",threshold==null||threshold==0);}JsonNode q=quiz.path("questions").get(0);score(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-one-of-three",f,caller,answers(answer(q,correctIds(q))),200),5,15,"33.3",threshold==null||threshold==0);ArrayNode qs=(ArrayNode)quiz.path("questions");ObjectNode all=answers(answer(qs.get(0),correctIds(qs.get(0))),answer(qs.get(1),correctIds(qs.get(1))),answer(qs.get(2),correctIds(qs.get(2))));score(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-all",f,caller,all,200),15,15,"100.0",true);}}QuizFixture boundary=fixture(LessonType.QUIZ);ObjectNode b=draft("multiple_choice_single","multiple_choice_single","multiple_choice_single");b.put("passingScore",67);JsonNode quiz=saveQuiz("QUIZ-013","two-of-three-boundary-definition",boundary,owner,b,200);entitled(boundary,buyer);JsonNode q0=quiz.path("questions").get(0),q1=quiz.path("questions").get(1);score(boundary,quiz,submit("QUIZ-013","two-of-three-rounded-HALF-UP",boundary,buyer,answers(answer(q0,correctIds(q0)),answer(q1,correctIds(q1))),200),10,15,"66.7",false);QuizFixture tie=fixture(LessonType.QUIZ);ObjectNode tieBody=draft("multiple_choice_single","multiple_choice_single");tieBody.put("passingScore",6);((ObjectNode)tieBody.path("questions").get(0)).put("points",1);((ObjectNode)tieBody.path("questions").get(1)).put("points",15);JsonNode tieQuiz=saveQuiz("QUIZ-013","HALF-UP-exact-half-definition",tie,owner,tieBody,200);entitled(tie,buyer);JsonNode tieQ=tieQuiz.path("questions").get(0);score(tie,tieQuiz,submit("QUIZ-013","6.25-rounded-to6.3-HALF-UP",tie,buyer,answers(answer(tieQ,correctIds(tieQ))),200),1,16,"6.3",true);}
 @Test void quiz014SubmissionAssociationAndMultiplicityValidation()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-014","mixed-definition",f,owner,draft("multiple_choice_single","true_false","multiple_choice_multi"),200);entitled(f,buyer);JsonNode a=quiz.path("questions").get(0),b=quiz.path("questions").get(1);for(User caller:List.of(buyer,owner,admin))for(String variant:List.of("unknown-question","invalid-question","blank-question","unknown-option","invalid-option","null-option","other-question-option","duplicate-answer","single-multiple","true-false-multiple")){ObjectNode body=answers(answer(a,correctIds(a)));ArrayNode answers=(ArrayNode)body.path("answers");ObjectNode ans=(ObjectNode)answers.get(0);switch(variant){case"unknown-question"->ans.put("questionId",UUID.randomUUID().toString());case"invalid-question"->ans.put("questionId","not-a-uuid");case"blank-question"->ans.put("questionId","  ");case"unknown-option"->ans.set("selectedOptionIds",mapper.valueToTree(List.of(UUID.randomUUID().toString())));case"invalid-option"->ans.set("selectedOptionIds",mapper.valueToTree(List.of("not-a-uuid")));case"null-option"->{ArrayNode ids=mapper.createArrayNode();ids.addNull();ans.set("selectedOptionIds",ids);}case"other-question-option"->ans.set("selectedOptionIds",mapper.valueToTree(correctIds(b)));case"duplicate-answer"->answers.add(ans.deepCopy());case"single-multiple"->ans.set("selectedOptionIds",mapper.valueToTree(List.of(a.path("options").get(0).path("id").asText(),a.path("options").get(1).path("id").asText())));case"true-false-multiple"->answers.set(0,answer(b,List.of(b.path("options").get(0).path("id").asText(),b.path("options").get(1).path("id").asText())));}JsonNode error=submit("QUIZ-014",role(caller)+"-"+variant,f,caller,body,400);assertTrue(error.path("errors").size()>0);assertEquals(0,quizAttempts.count());assertEquals(quiz,authorRead("QUIZ-014",role(caller)+"-unchanged-"+variant,f,owner,200));}}
