 static JsonNode protectedMutation(JsonNode source){JsonNode n=source.deepCopy();if(n.path("type").asText().equals("DOWNLOAD"))for(JsonNode section:n.path("details").path("sections"))for(JsonNode file:section.path("files"))((com.fasterxml.jackson.databind.node.ObjectNode)file).putNull("url");return n;}
