 void consultationBoundary(String c,String kind,String variant,String key,String error)throws Exception{int unexpectedRepairs=0;for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Map<String,Object>d=new LinkedHashMap<>();d.put("durationMinutes",30);d.put("meetingMethod","ZOOM");d.put("weeklyAvailability",List.of(availability(true,false)));Map<String,Object>b=payload(ProductType.CONSULTATION,owner);b.put("status",state.name());b.put("price","10");Map<String,Object>fix=new LinkedHashMap<>();switch(kind){case"price"->{b.put("price","0");fix.put("price","10");}case"duration"->{d.put("durationMinutes",Integer.parseInt(variant));fix.put("details",Map.of("durationMinutes",30));}case"method"->{d.put("meetingMethod",null);fix.put("details",Map.of("meetingMethod","ZOOM"));}case"location"->{d.put("meetingMethod","OTHER");d.put("customLocation","  ");fix.put("details",Map.of("customLocation","QA synthetic meeting instructions"));}case"disabled"->{d.put("weeklyAvailability",List.of(availability(false,false)));fix.put("details",Map.of("weeklyAvailability",List.of(availability(true,false))));}case"overlap"->{d.put("weeklyAvailability",List.of(availability(true,true)));fix.put("details",Map.of("weeklyAvailability",List.of(availability(true,false))));}}b.put("details",d);Product p=entity(create(c,role(caller)+state+"-otherwise-ready-draft-"+kind+variant,caller,b,201));rejectPublication(c,p,caller,key,error);if(kind.equals("disabled")||kind.equals("overlap")){JsonNode before=read(c,role(caller)+state+"-before-weekday-replacement",p,owner);Map<String,Object> requested=new LinkedHashMap<>(fix);requested.put("status","PUBLISHED");var req=mutation(patch("/api/products/"+p.getId()),caller).content(mapper.writeValueAsString(requested));var response=mvc.perform(req).andReturn();int status=response.getResponse().getStatus();JsonNode body=mapper.readTree(response.getResponse().getContentAsString());String msg=body.path("message").asText().toLowerCase();Map<String,Object>obs=new LinkedHashMap<>();obs.put("case_id",c);obs.put("label",role(caller)+state+"-repair-existing-Monday");obs.put("actual_status",status);obs.put("expected_status",200);obs.put("availability_unique_constraint_error",msg.contains("unique")&&msg.contains("consultation_availability_days"));obs.put("observed_at",java.time.Instant.now().toString());observations.add(obs);if(status!=200){unexpectedRepairs++;assertEquals(400,status);assertTrue((Boolean)obs.get("availability_unique_constraint_error"));assertEquals(before,read(c,role(caller)+state+"-repair-rollback",p,owner));patchBody(c,role(caller)+state+"-clear-availability-control",p,caller,Map.of("details",Map.of("weeklyAvailability",List.of())),200);acceptedPublication(c,p,caller,fix);}else acceptedPublication(c,p,caller,Map.of());}else acceptedPublication(c,p,caller,fix);}assertEquals(0,unexpectedRepairs,c+" existing weekday corrected in one PATCH must save and publish");}
