    MvcResult result=mvc.perform(req).andReturn();int status=result.getResponse().getStatus();String text=result.getResponse().getContentAsString();JsonNode body=text.isEmpty()?mapper.nullNode():mapper.readTree(text);
    Map<String,Object> row=new LinkedHashMap<>();row.put("case_id",caseId);row.put("label",label);row.put("method",req.buildRequest(new org.springframework.mock.web.MockServletContext()).getMethod());row.put("actual_status",status);row.put("expected_status",expected);row.put("orders",orders.count());row.put("attempts",attempts.count());row.put("events",events.count());row.put("entitlements",grants.count());row.put("observed_at",Instant.now().toString());observations.add(row);
    assertEquals(expected,status,caseId+" "+label+" HTTP status");return body;
  }
