public class CatalogBatchRunner{
 public static void main(String[] args)throws Exception{
 Class<?> cls=Class.forName("com.myproject.video.video_platform.controller.commerce."+args[0]);Path output=Path.of(args[1]);var builder=LauncherDiscoveryRequestBuilder.request();int selected=0;for(var method:cls.getDeclaredMethods())if(method.isAnnotationPresent(org.junit.jupiter.api.Test.class)&&(args.length==2||Arrays.asList(args).subList(2,args.length).contains(method.getName()))){builder.selectors(DiscoverySelectors.selectMethod(cls,method.getName()));selected++;}if(selected==0)throw new IllegalArgumentException("No declared catalog methods selected");
 List<Map<String,Object>> results=new ArrayList<>();var listener=new TestExecutionListener(){public void executionFinished(TestIdentifier id,org.junit.platform.engine.TestExecutionResult r){if(id.isTest()){Map<String,Object> m=new LinkedHashMap<>();m.put("test",id.getDisplayName());m.put("status",r.getStatus().name());r.getThrowable().ifPresent(e->{m.put("error_type",e.getClass().getName());if(e instanceof org.opentest4j.AssertionFailedError)m.put("assertion",e.getMessage());m.put("test_stack",Arrays.stream(e.getStackTrace()).filter(x->x.getClassName().startsWith("com.myproject.video.video_platform.controller.commerce.Catalog")).map(Object::toString).toList());});results.add(m);}}};var summary=new SummaryGeneratingListener();var launcher=LauncherFactory.create();launcher.registerTestExecutionListeners(listener,summary);launcher.execute(builder.build());Map<String,Object> result=new LinkedHashMap<>();result.put("executed_at",java.time.Instant.now().toString());result.put("test_class",cls.getSimpleName());result.put("tests_found",summary.getSummary().getTestsFoundCount());result.put("tests_passed",summary.getSummary().getTestsSucceededCount());result.put("tests_failed",summary.getSummary().getTestsFailedCount());result.put("tests",results);result.put("observations",CatalogCheckoutMatrixTest.observations);new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(output.toFile(),result);System.out.println("CATALOG_BATCH_RESULT tests="+summary.getSummary().getTestsFoundCount()+" passed="+summary.getSummary().getTestsSucceededCount()+" failed="+summary.getSummary().getTestsFailedCount());System.exit(summary.getSummary().getTotalFailureCount()>0?1:0);
 }
}

