 @Test void quiz012MultiExactSetSubsetSupersetDuplicates()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-012","multi-definition",f,owner,draft("multiple_choice_multi"),200);entitled(f,buyer);JsonNode q=quiz.path("questions").get(0);List<String>correct=correctIds(q);String wrong=q.path("options").get(2).path("id").asText();List<List<String>>sets=List.of(correct,List.of(correct.get(0)),List.of(correct.get(0),correct.get(1),wrong),List.of(correct.get(0),correct.get(1),correct.get(0),correct.get(1)));for(User caller:List.of(buyer,owner,admin))for(int i=0;i<sets.size();i++){boolean earns=i==0||i==3;JsonNode result=submit("QUIZ-012",role(caller)+"-answer-set-"+i,f,caller,answers(answer(q,sets.get(i))),200);score(f,quiz,result,earns?5:0,5,earns?"100.0":"0.0",earns);assertEquals(earns,result.path("questions").get(0).path("correct").asBoolean());}assertEquals(12,quizAttempts.count());for(var a:quizAttempts.findAll()){JsonNode normalized=mapper.readTree(a.getAnswersJson());List<String> ids=mapper.convertValue(normalized.path(q.path("id").asText()),List.class);assertEquals(new HashSet<>(ids).size(),ids.size());if(a.getTotalPointsAchieved()>0)assertEquals(new HashSet<>(correct),new HashSet<>(ids));else assertTrue(new HashSet<>(ids).equals(new HashSet<>(sets.get(1)))||new HashSet<>(ids).equals(new HashSet<>(sets.get(2))));}}
 @Test void quiz013OmittedAnswersRoundingAndThresholdEquality()throws Exception{for(Integer threshold:Arrays.asList(0,100,null)){QuizFixture f=fixture(LessonType.QUIZ);ObjectNode b=draft("multiple_choice_single","multiple_choice_single","multiple_choice_single");if(threshold==null)b.putNull("passingScore");else b.put("passingScore",threshold);JsonNode quiz=saveQuiz("QUIZ-013","threshold-"+threshold+"-definition",f,owner,b,200);entitled(f,buyer);for(User caller:List.of(buyer,owner,admin)){for(String shape:List.of("empty","omitted","null")){ObjectNode body=shape.equals("empty")?answers():mapper.createObjectNode();if(shape.equals("null"))body.putNull("answers");scoreWithFeedback(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-"+shape,f,caller,body,200),0,15,"0.0",threshold==null||threshold==0);}JsonNode q=quiz.path("questions").get(0);scoreWithFeedback(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-one-of-three",f,caller,answers(answer(q,correctIds(q))),200),5,15,"33.3",threshold==null||threshold==0);ArrayNode qs=(ArrayNode)quiz.path("questions");ObjectNode all=answers(answer(qs.get(0),correctIds(qs.get(0))),answer(qs.get(1),correctIds(qs.get(1))),answer(qs.get(2),correctIds(qs.get(2))));scoreWithFeedback(f,quiz,submit("QUIZ-013",role(caller)+"-threshold-"+threshold+"-all",f,caller,all,200),15,15,"100.0",true);}}QuizFixture boundary=fixture(LessonType.QUIZ);ObjectNode b=draft("multiple_choice_single","multiple_choice_single","multiple_choice_single");b.put("passingScore",67);JsonNode quiz=saveQuiz("QUIZ-013","two-of-three-boundary-definition",boundary,owner,b,200);entitled(boundary,buyer);JsonNode q0=quiz.path("questions").get(0),q1=quiz.path("questions").get(1);scoreWithFeedback(boundary,quiz,submit("QUIZ-013","two-of-three-rounded-HALF-UP",boundary,buyer,answers(answer(q0,correctIds(q0)),answer(q1,correctIds(q1))),200),10,15,"66.7",false);QuizFixture tie=fixture(LessonType.QUIZ);ObjectNode tieBody=draft("multiple_choice_single","multiple_choice_single");tieBody.put("passingScore",6);((ObjectNode)tieBody.path("questions").get(0)).put("points",1);((ObjectNode)tieBody.path("questions").get(1)).put("points",15);JsonNode tieQuiz=saveQuiz("QUIZ-013","HALF-UP-exact-half-definition",tie,owner,tieBody,200);entitled(tie,buyer);JsonNode tieQ=tieQuiz.path("questions").get(0);scoreWithFeedback(tie,tieQuiz,submit("QUIZ-013","6.25-rounded-to6.3-HALF-UP",tie,buyer,answers(answer(tieQ,correctIds(tieQ))),200),1,16,"6.3",true);}
 @Test void quiz014SubmissionAssociationAndMultiplicityValidation()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-014","mixed-definition",f,owner,draft("multiple_choice_single","true_false","multiple_choice_multi"),200);entitled(f,buyer);JsonNode a=quiz.path("questions").get(0),b=quiz.path("questions").get(1);for(User caller:List.of(buyer,owner,admin))for(String variant:List.of("unknown-question","invalid-question","blank-question","unknown-option","invalid-option","null-option","other-question-option","duplicate-answer","single-multiple","true-false-multiple")){ObjectNode body=answers(answer(a,correctIds(a)));ArrayNode answers=(ArrayNode)body.path("answers");ObjectNode ans=(ObjectNode)answers.get(0);switch(variant){case"unknown-question"->ans.put("questionId",UUID.randomUUID().toString());case"invalid-question"->ans.put("questionId","not-a-uuid");case"blank-question"->ans.put("questionId","  ");case"unknown-option"->ans.set("selectedOptionIds",mapper.valueToTree(List.of(UUID.randomUUID().toString())));case"invalid-option"->ans.set("selectedOptionIds",mapper.valueToTree(List.of("not-a-uuid")));case"null-option"->{ArrayNode ids=mapper.createArrayNode();ids.addNull();ans.set("selectedOptionIds",ids);}case"other-question-option"->ans.set("selectedOptionIds",mapper.valueToTree(correctIds(b)));case"duplicate-answer"->answers.add(ans.deepCopy());case"single-multiple"->ans.set("selectedOptionIds",mapper.valueToTree(List.of(a.path("options").get(0).path("id").asText(),a.path("options").get(1).path("id").asText())));case"true-false-multiple"->answers.set(0,answer(b,List.of(b.path("options").get(0).path("id").asText(),b.path("options").get(1).path("id").asText())));}JsonNode error=submit("QUIZ-014",role(caller)+"-"+variant,f,caller,body,400);assertTrue(error.path("errors").size()>0);assertEquals(0,quizAttempts.count());assertEquals(quiz,authorRead("QUIZ-014",role(caller)+"-unchanged-"+variant,f,owner,200));}}
 @Test void quiz015RepeatedSubmissionPersistsSeparateAttemptsNoHistoryRoute()throws Exception{QuizFixture f=fixture(LessonType.QUIZ);JsonNode quiz=saveQuiz("QUIZ-015","definition",f,owner,draft("multiple_choice_single"),200);entitled(f,buyer);JsonNode q=quiz.path("questions").get(0);ObjectNode body=answers(answer(q,correctIds(q)));JsonNode first=submit("QUIZ-015","first-valid-attempt",f,buyer,body,200),second=submit("QUIZ-015","second-identical-attempt",f,buyer,body,200);assertEquals(first,second);score(f,quiz,second,5,5,"100.0",true);assertEquals(2,quizAttempts.count());Set<UUID>ids=new HashSet<>();for(var attempt:quizAttempts.findAll()){assertTrue(ids.add(attempt.getId()));assertEquals(buyer.getUserId(),attempt.getUser().getUserId());assertEquals(f.l().getId(),attempt.getLesson().getId());assertEquals(quiz.path("id").asText(),attempt.getQuiz().getId().toString());assertNotNull(attempt.getSubmittedAt());assertEquals(5,attempt.getTotalPointsPossible());assertEquals(5,attempt.getTotalPointsAchieved());assertEquals(0,new BigDecimal("100.0").compareTo(attempt.getPercentage()));assertTrue(attempt.isPassed());assertEquals(correctIds(q),mapper.convertValue(mapper.readTree(attempt.getAnswersJson()).path(q.path("id").asText()),List.class));}read("QUIZ-015","supported-product-reload",f.p(),buyer);JsonNode library=perform("QUIZ-015","supported-library-reload",get("/api/entitlements/me").cookie(auth(buyer)),200);assertEquals(1,library.size());assertEquals(f.p().getId().toString(),library.get(0).path("product").path("id").asText());assertEquals(2,quizAttempts.count());}
